import { test, expect } from '@playwright/test';

test.describe('User Profile - Change Password', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/profile');
    await page.getByRole('button', { name: 'Edit Profile' }).click();
  });

  test('should display change password form', async ({ page }) => {
    await page.getByText('Change Password').click();
    const changePasswordHeading = await page.getByText('Change Your Password');
    await expect(changePasswordHeading).toBeVisible();
  });

  test('should successfully change password', async ({ page }) => {
    await page.getByLabel('Current Password').fill('oldPassword123');
    await page.getByLabel('New Password').fill('newPassword123');
    await page.getByLabel('Confirm New Password').fill('newPassword123');
    await page.getByRole('button', { name: 'Save Changes' }).click();

    const successMessage = await page.getByText('Your password has been changed successfully.');
    await expect(successMessage).toBeVisible();
  });
});
